theme.globalCss:
.volturianoStamp {
  display: inline-flex;
  align-items: center;
  justify-content: flex-start;
  gap: 0; 
  padding: 0px 5px;
  width: 55px; 
  height: 55px; 
  border-radius: 14px;
  text-decoration: none;
  overflow: hidden;
  white-space: nowrap;
  border: 2px solid transparent;
  background-image: 
    linear-gradient(to bottom, #0a0a0a, #141414),
    linear-gradient(135deg, rgba(255,255,255,0.9) 0%, rgba(80,80,80,0.5) 50%, rgba(255,255,255,0.8) 100%);
  background-origin: padding-box, border-box;
  background-clip: padding-box, border-box;
  box-shadow: 0px 4px 30px -5px rgba(255, 255, 255, 0.15);
  transition: width 0.5s cubic-bezier(0.25, 0.8, 0.25, 1), padding 0.5s cubic-bezier(0.25, 0.8, 0.25, 1), box-shadow 0.3s ease, transform 0.3s ease;
}

.volturianoStamp:hover {
  width: 230px; 
  padding: 0px 20px; 
  box-shadow: 0px 8px 40px -4px rgba(255, 255, 255, 0.35);
}

.stampContent {
  display: flex;
  align-items: center;
  gap: 15px; 
  opacity: 0;
  max-width: 0;
  padding-right: 0;
  overflow: hidden;
  transition: max-width 0.5s cubic-bezier(0.25, 0.8, 0.25, 1), opacity 0.4s ease-out, padding-right 0.5s cubic-bezier(0.25, 0.8, 0.25, 1), transform 0.4s ease-out;
}

.volturianoStamp:hover .stampContent {
  opacity: 1;
  max-width: 200px;
  padding-right: 15px; 
}

.stampText {
  font-family: sans-serif;
  font-size: 14px;
  font-weight: 800;
  letter-spacing: 2.5px;
  text-transform: uppercase;
  background: linear-gradient(to bottom, #ffffff 0%, #b0b0b0 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}

.stampSeparator {
  width: 1.5px;
  height: 24px;
  background: linear-gradient(to bottom, #ffffff, rgba(255,255,255,0.5));
  border-radius: 10px;
}

.stampLogo {
  height: 45px;
  width: auto;
  filter: brightness(0) invert(1);
}
